// spec: specs/orders.md §10 · кейс .qa/tests/orders/ord-26-walk-in-stock-limit.md
// seed: tests/seed.admin.spec.ts
// #80bb3c (עבר QA 25.10; решение пользователя 20.10 — нельзя продать больше реального остатка):
//   «+» останавливается на остатке («זו כל הכמות במלאי (N)»); ввод больше остатка → после ухода с поля «במלאי N בלבד — לא ניתן
//   למכור יותר», aria-invalid; «רישום המכירה» → баннер «הכמות של <שם> אינה תקינה…», окно подтверждения не открывается;
//   товар с остатком 0 — в списке «אזל מהמלאי» (aria-disabled), по מק"ט + Enter — «<שם> — אזל מהמלאי.»; 1.5 → «כמות — מספר שלם בלבד»;
//   предупреждения «יימכרו ללא מלאי» больше нет.
// Продажа НЕ регистрируется (необратима): «רישום המכירה» жмётся только с неверным количеством, «אישור המכירה» — никогда.
// Данные: свои товары QA-AUTO-80bb-<ts> (₪1): A — остаток 2 «ללא מקום», O — без остатка; afterAll — удаляются.
import { test, expect, Page } from '@playwright/test';
import { auth, createProduct, createStockedProduct, cleanup } from './_qa-order';

test.use({ storageState: auth('admin') });

const esc = (s: string) => s.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
const EMPTY = 'עדיין לא נוספו פריטים — חפש מוצר למטה כדי להתחיל.';

test.describe('orders — מכירה מיידית: אי אפשר למכור יותר מהמלאי (#80bb3c)', () => {
  test.describe.configure({ mode: 'default' });
  const ts = `${String(Date.now()).slice(-7)}${Math.floor(Math.random() * 10)}`;
  const A = `QA-AUTO-80bb-${ts} A`;
  const O = `QA-AUTO-80bb-${ts} O`;
  const SKU_A = `Q80BB-${ts}-A`;
  const SKU_O = `Q80BB-${ts}-O`;
  const created: string[] = [];

  const search = (page: Page) => page.getByRole('combobox', { name: 'חיפוש מוצר להוספה למכירה' });
  const results = (page: Page) => page.getByRole('listbox', { name: 'תוצאות חיפוש מוצרים' });
  const optionOf = (page: Page, name: string) => results(page).getByRole('option', { name: new RegExp(`^${esc(name)}\\s+(נותרו|אזל)`) });
  const qty = (page: Page, name = A) => page.getByRole('textbox', { name: `כמות — ${name}`, exact: true });
  const plus = (page: Page) => page.getByRole('button', { name: `הוספת יחידה — ${A}`, exact: true });
  const register = (page: Page) => page.getByRole('button', { name: 'רישום המכירה' });
  const allRows = (page: Page) => page.getByRole('textbox', { name: /^כמות — / });

  async function open(page: Page) {
    await page.goto('/orders/walk-in');
    await expect(page.getByRole('heading', { level: 1, name: 'מכירה מיידית' })).toBeVisible({ timeout: 30_000 });
  }
  async function addA(page: Page) {
    await open(page);
    await search(page).fill(SKU_A);
    await search(page).press('Enter'); // точный מק"ט + Enter добавляет сразу
    await expect(qty(page)).toHaveValue('1', { timeout: 15_000 });
  }
  async function noOverStockWarning(page: Page) {
    await expect(page.getByText(/יימכרו ללא מלאי|המכירה תירשם בכל זאת/)).toHaveCount(0);
  }

  test.beforeAll(async ({ browser }) => {
    test.setTimeout(180_000);
    const ctx = await browser.newContext({ storageState: auth('admin'), locale: 'he-IL', viewport: { width: 1440, height: 900 } });
    try {
      const page = await ctx.newPage();
      created.push(A);
      await createStockedProduct(page, A, SKU_A, 1, 2);
      created.push(O);
      await createProduct(page, O, SKU_O, 1);
    } finally { await ctx.close(); }
  });
  test.afterAll(async ({ browser }) => {
    test.setTimeout(120_000);
    await cleanup(browser, [], created);
  });

  test.skip('«+» נעצר בכמות המלאי (2): «זו כל הכמות במלאי (2)» #80bb3c @desktop @orders @data', { annotation: { type: 'skip', description: 'временно отключено 26.10 по просьбе клиента (#e7e338, лимит остатка снят); вернуть вместе с #e02e48 — knowledge/stock-logic-snapshot-2026-10-26.md §5' } }, async ({ page }) => {
    await addA(page);
    await plus(page).click();
    await expect(qty(page)).toHaveValue('2');
    await expect(plus(page)).toBeDisabled();
    await expect(page.getByText('זו כל הכמות במלאי (2)')).toBeVisible();
    await expect(page.getByText('סה"כ לתשלום').locator('..')).toContainText('₪2.00');
    await noOverStockWarning(page);
    await page.getByRole('button', { name: 'חזרה להזמנות' }).click(); // продажу не регистрируем
  });

  test.skip('הקלדת 3 / 5: «במלאי 2 בלבד — לא ניתן למכור יותר», «רישום המכירה» — באנר ובלי חלון אישור #80bb3c @desktop @orders @data', { annotation: { type: 'skip', description: 'временно отключено 26.10 по просьбе клиента (#e7e338, лимит остатка снят); вернуть вместе с #e02e48 — knowledge/stock-logic-snapshot-2026-10-26.md §5' } }, async ({ page }) => {
    await addA(page);
    const banner = page.getByText(`הכמות של ${A} אינה תקינה. עדכן אותה ונסה שוב.`, { exact: true });
    for (const v of ['3', '5']) {
      await qty(page).fill(v);
      await qty(page).press('Tab');
      await expect(page.getByText('במלאי 2 בלבד — לא ניתן למכור יותר', { exact: true }), `сообщение для ${v}`).toBeVisible();
      await expect(qty(page), `поле помечено неверным для ${v}`).toHaveAttribute('aria-invalid', 'true');
      await register(page).click();
      await expect(banner, `баннер для ${v}`).toBeVisible();
      await expect(page.getByRole('dialog'), `окно подтверждения не открывается для ${v}`).toHaveCount(0);
    }
    await noOverStockWarning(page);
    await page.getByRole('button', { name: 'חזרה להזמנות' }).click(); // продажу не регистрируем
  });

  test('כמות 1.5 — «כמות — מספר שלם בלבד» #80bb3c @desktop @orders @data', async ({ page }) => {
    await addA(page);
    await qty(page).fill('1.5');
    await qty(page).press('Tab');
    await expect(page.getByText('כמות — מספר שלם בלבד', { exact: true })).toBeVisible();
    await expect(qty(page)).toHaveValue('1.5');
    await page.getByRole('button', { name: 'חזרה להזמנות' }).click();
  });

  test.skip('מוצר במלאי 0: ברשימה «אזל מהמלאי» ולא נוסף בלחיצה; מק"ט + Enter — «… — אזל מהמלאי.» #80bb3c @desktop @orders @data', { annotation: { type: 'skip', description: 'временно отключено 26.10 по просьбе клиента (#e7e338, лимит остатка снят); вернуть вместе с #e02e48 — knowledge/stock-logic-snapshot-2026-10-26.md §5' } }, async ({ page }) => {
    await open(page);
    await search(page).fill(O);
    const opt = optionOf(page, O);
    await expect(opt).toContainText('אזל מהמלאי', { timeout: 20_000 });
    await expect(opt).toHaveAttribute('aria-disabled', 'true');
    await opt.click({ force: true });
    await expect(qty(page, O)).toHaveCount(0);

    await search(page).fill(SKU_O);
    await search(page).press('Enter');
    await expect(page.getByText(`${O} — אזל מהמלאי.`, { exact: true })).toBeVisible({ timeout: 15_000 });
    await expect(allRows(page)).toHaveCount(0);
    await expect(page.getByText(EMPTY)).toBeVisible();
    await expect(register(page)).toBeDisabled();
    await noOverStockWarning(page);
  });
});
